def main():
    """Read JSON Lines from stdin until EOF; one response object per line."""
    inp = sys.stdin.buffer
    out = sys.stdout
    write = out.write
    while True:
        try:
            raw = inp.readline()
        except Exception:
            traceback.print_exc()
            break
        if not raw:
            break
        if raw.endswith(b'\n'):
            raw = raw[:-1]
        try:
            resp = process_line(raw)
            text = json.dumps(resp, separators=(',', ':'))
        except Exception:
            traceback.print_exc()
            text = '{"id":null,"status":"error","error":"malformed_json"}'
        try:
            write(text)
            write('\n')
            out.flush()
        except Exception:
            traceback.print_exc()
            break
